def calculate_depth(group: str) -> int:
    if not group:
        return 0
    depth = 0
    for char in group:
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
    return depth

for group in groups:
    results.append(calculate_depth(group))

return results

